export const StatCard = ({
  label,
  value,
  delta,
  icon,
  tone = 'brand',
}: {
  label: string;
  value: string;
  delta?: { value: string; positive?: boolean };
  icon: React.ReactNode;
  tone?: 'brand' | 'sky' | 'amber' | 'violet';
}) => {
  const tones = {
    brand: 'from-brand-500/15 to-brand-500/0 text-brand-600 dark:text-brand-300',
    sky: 'from-sky-500/15 to-sky-500/0 text-sky-600 dark:text-sky-300',
    amber: 'from-amber-500/15 to-amber-500/0 text-amber-600 dark:text-amber-300',
    violet: 'from-violet-500/15 to-violet-500/0 text-violet-600 dark:text-violet-300',
  };
  return (
    <div className="card group relative overflow-hidden p-5 transition-transform duration-300 hover:-translate-y-1">
      <div className={cn('absolute inset-x-0 top-0 h-24 bg-gradient-to-b opacity-80', tones[tone])} />
      <div className="relative flex items-start justify-between">
        <div>
          <p className="text-xs font-bold uppercase tracking-wider text-[var(--muted)]">{label}</p>
          <p className="mt-2 font-display text-2xl font-extrabold tracking-tight sm:text-[27px]">{value}</p>
          {delta && (
            <p className={cn('mt-2 flex items-center gap-1 text-xs font-bold', delta.positive ? 'text-brand-600 dark:text-brand-400' : 'text-rose-500')}>
              <span>{delta.positive ? '▲' : '▼'}</span> {delta.value}
            </p>
          )}
        </div>
        <div className={cn('flex h-11 w-11 items-center justify-center rounded-2xl bg-[var(--surface)] shadow-sm', tones[tone])}>
          {icon}
        </div>
      </div>
    </div>
  );
};

export const Modal = ({
  open,
  onClose,
  title,
  subtitle,
  children,
  wide = false,
}: {
  open: boolean;
  onClose: () => void;
  title: string;
  subtitle?: string;
  children: React.ReactNode;
  wide?: boolean;
}) => {
  if (!open) return null;
  return (
    <div className="fixed inset-0 z-[80] flex items-end justify-center bg-slate-950/55 p-0 backdrop-blur-sm sm:items-center sm:p-4" onClick={onClose}>
      <div
        className={cn(
          'animate-fade-up max-h-[92vh] w-full overflow-y-auto rounded-t-3xl border bg-[var(--surface)] p-5 shadow-2xl sm:rounded-3xl sm:p-6',
          wide ? 'sm:max-w-3xl' : 'sm:max-w-lg',
        )}
        style={{ borderColor: 'var(--border)' }}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="mb-5 flex items-start justify-between gap-4">
          <div>
            <h2 className="font-display text-xl font-extrabold">{title}</h2>
            {subtitle && <p className="mt-1 text-sm text-[var(--muted)]">{subtitle}</p>}
          </div>
          <button className="icon-btn shrink-0" onClick={onClose} aria-label="close">
            <X size={18} />
          </button>
        </div>
        {children}
      </div>
    </div>
  );
};

