export const AreaChart = ({
  data,
  height = 220,
  color = '#10b981',
  suffix = '',
}: {
  data: { label: string; value: number }[];
  height?: number;
  color?: string;
  suffix?: string;
}) => {
  const max = Math.max(...data.map((d) => d.value)) * 1.18;
  const w = 620;
  const h = 200;
  const step = w / Math.max(1, data.length - 1);
  const points = data.map((d, i) => ({ x: i * step, y: h - (d.value / max) * h }));
  const line = points.map((p, i) => `${i === 0 ? 'M' : 'L'}${p.x},${p.y}`).join(' ');
  const area = `${line} L${w},${h} L0,${h} Z`;
  return (
    <div className="w-full">
      <svg viewBox={`0 0 ${w} ${h}`} style={{ height }} className="w-full overflow-visible">
        <defs>
          <linearGradient id="areaFill" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={color} stopOpacity="0.32" />
            <stop offset="100%" stopColor={color} stopOpacity="0" />
          </linearGradient>
        </defs>
        {[0.25, 0.5, 0.75, 1].map((p) => (
          <line key={p} x1="0" x2={w} y1={h * p} y2={h * p} stroke="currentColor" strokeOpacity="0.08" strokeDasharray="4 6" />
        ))}
        <path d={area} fill="url(#areaFill)" />
        <path d={line} fill="none" stroke={color} strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round" />
        {points.map((p, i) => (
          <g key={i}>
            <circle cx={p.x} cy={p.y} r="7" fill={color} opacity="0.12" />
            <circle cx={p.x} cy={p.y} r="3.5" fill={color} stroke="white" strokeWidth="2" />
          </g>
        ))}
      </svg>
      <div className="mt-2 flex justify-between px-1 text-[11px] font-semibold text-[var(--muted)]">
        {data.map((d) => (
          <span key={d.label}>{d.label}</span>
        ))}
      </div>
      <div className="mt-1 text-right text-[11px] font-semibold text-[var(--muted)]">
        max {Math.round(max)}{suffix}
      </div>
    </div>
  );
};

export const Donut = ({
  segments,
  total,
  centerLabel,
  centerValue,
}: {
  segments: { label: string; value: number; color: string }[];
  total: number;
  centerLabel: string;
  centerValue: string;
}) => {
  const circumference = 2 * Math.PI * 42;
  let offset = 0;
  return (
    <div className="flex flex-col items-center gap-5 sm:flex-row sm:items-center">
      <div className="relative h-40 w-40 shrink-0">
        <svg viewBox="0 0 100 100" className="h-full w-full -rotate-90">
          <circle cx="50" cy="50" r="42" fill="none" stroke="var(--surface-3)" strokeWidth="11" />
          {segments.map((s) => {
            const len = total ? (s.value / total) * circumference : 0;
            const el = (
              <circle
                key={s.label}
                cx="50"
                cy="50"
                r="42"
                fill="none"
                stroke={s.color}
                strokeWidth="11"
                strokeDasharray={`${len} ${circumference - len}`}
                strokeDashoffset={-offset}
                strokeLinecap="round"
              />
            );
            offset += len;
            return el;
          })}
        </svg>
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          <span className="font-display text-2xl font-extrabold">{centerValue}</span>
          <span className="text-[10px] font-bold uppercase tracking-wider text-[var(--muted)]">{centerLabel}</span>
        </div>
      </div>
      <div className="w-full space-y-2.5">
        {segments.map((s) => (
          <div key={s.label} className="flex items-center justify-between gap-3 text-sm">
            <span className="flex items-center gap-2 font-semibold">
              <span className="h-2.5 w-2.5 rounded-full" style={{ background: s.color }} />
              {s.label}
            </span>
            <span className="text-[var(--muted)]">{total ? Math.round((s.value / total) * 100) : 0}%</span>
          </div>
        ))}
      </div>
    </div>
  );
};

